<?php declare(strict_types=1);$money=static fn(float$value):string=>'R$ '.number_format($value,2,',','.'); ?><div class="actions"><div><span class="status">ADM · Cursos</span><h1>Cursos e preços</h1><p class="meta">Os cursos vêm do Moodle. Aqui o ADM completa a política comercial.</p></div><form method="post" action="<?= $escape($basePath) ?>/admin/finance/products/sync"><?= $csrfField ?><button class="button-primary" type="submit"><i class="fa-solid fa-rotate"></i> Sincronizar cursos do Moodle</button></form></div><?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?><div class="alert alert-warning"><strong>Fluxo:</strong> sincronize os cursos e edite cada item pendente para informar valor total, número máximo de parcelas e ativá-lo.</div><div class="table-responsive"><table><thead><tr><th>Curso do Moodle</th><th>Unidade</th><th>Valor total</th><th>Parcelas</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php if($products===[]):?><tr><td colspan="6">Clique em “Sincronizar cursos do Moodle” para iniciar.</td></tr><?php endif;?><?php foreach($products as$product):$pending=(float)$product['value']<5;?><tr><td><strong><?= $escape($product['name']) ?></strong><?php if($product['moodle_shortname']):?><br><small><?= $escape($product['moodle_shortname']) ?></small><?php endif;?></td><td><?= $escape($product['unit_name']?:'Todas as unidades') ?></td><td><?= $pending?'—':$escape($money((float)$product['value'])) ?></td><td><?= $pending?'—':'Até '.(int)$product['max_installments'].'x' ?></td><td><span class="connection-badge"><?= $pending?'Aguardando valores':((int)$product['is_active']===1?'Ativo':'Inativo') ?></span></td><td><a class="button-icon" title="Configurar curso" href="<?= $escape($basePath) ?>/admin/finance/products/<?= (int)$product['id'] ?>/edit"><i class="fa-solid fa-pen"></i></a></td></tr><?php endforeach;?></tbody></table></div>
